def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        # Start of a new field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the field
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # The closing quote must be followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(''.join(field))
        else:
            # Unquoted field - runs until comma or end of line
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain a double quote
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < n:
                i += 1  # Skip the comma

    return fields

